/**
 * POST /recipes — ChefBOT (PRD §3/§4): picked ingredients + time + diet in,
 * exactly three home-cook recipes out, generated by Gemini and validated by
 * the shared schema before anything reaches the client.
 */

import {
  validateRecipesRequest,
  validateRecipesResponse,
  type RecipeRequest,
} from "../../../shared/recipe-schema";
import type { WorkerEnv } from "../env";
import { callGemini, DEFAULT_GEMINI_MODEL } from "../lib/gemini";
import { errorResponse, json, type HeaderMap } from "../lib/http";

export const MAX_BODY_BYTES = 4096;

/** Schema handed to Gemini (OpenAPI subset); the shared validator still has the final word. */
const RECIPES_SCHEMA = {
  type: "OBJECT",
  properties: {
    recipes: {
      type: "ARRAY",
      minItems: 3,
      maxItems: 3,
      items: {
        type: "OBJECT",
        properties: {
          title: { type: "STRING" },
          emoji: { type: "STRING" },
          minutes: { type: "INTEGER" },
          uses: { type: "ARRAY", items: { type: "STRING" } },
          missing: { type: "ARRAY", items: { type: "STRING" } },
          steps: { type: "ARRAY", items: { type: "STRING" }, minItems: 1, maxItems: 8 },
        },
        required: ["title", "emoji", "minutes", "uses", "missing", "steps"],
        propertyOrdering: ["title", "emoji", "minutes", "uses", "missing", "steps"],
      },
    },
  },
  required: ["recipes"],
};

function systemPrompt(request: RecipeRequest): string {
  return [
    "You are ChefBOT, a practical home-cooking recipe assistant.",
    "Return ONLY JSON matching the schema, no markdown, no commentary.",
    "Rules: exactly 3 recipes; unique titles; title at most 60 characters;",
    `emoji: one short food emoji; minutes: integer from 1 to ${request.maxMinutes};`,
    "uses: the selected ingredient ids the recipe actually uses (lowercase, from the user's list only);",
    "missing: at most 4 pantry/fresh items the cook could add but can live without (lowercase);",
    "steps: 1 to 8 short imperative sentences a home cook follows in order (max 300 chars each);",
    "Recipes must be realistic, tested-style home cooking with common techniques.",
    request.vegetarian
      ? "Recipes MUST be strictly vegetarian (no meat, fish, poultry, or seafood)."
      : "Recipes may use any ingredients.",
  ].join(" ");
}

export async function handleRecipes(
  request: Request,
  env: WorkerEnv,
  headers: HeaderMap,
): Promise<Response> {
  const contentLength = Number(request.headers.get("Content-Length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > MAX_BODY_BYTES) {
    return errorResponse(413, "payload_too_large", "Request body too large.", headers);
  }
  const text = await request.text();
  if (text.length > MAX_BODY_BYTES) {
    return errorResponse(413, "payload_too_large", "Request body too large.", headers);
  }

  let parsedBody: unknown;
  try {
    parsedBody = JSON.parse(text);
  } catch {
    return errorResponse(400, "invalid_json", "Request body must be JSON.", headers);
  }

  const validated = validateRecipesRequest(parsedBody);
  if (!validated.ok) {
    return errorResponse(400, "invalid_request", validated.reason, headers);
  }

  if (!env.GEMINI_API_KEY) {
    return errorResponse(503, "ai_not_configured", "Recipe service is not configured.", headers);
  }

  const outcome = await callGemini({
    apiKey: env.GEMINI_API_KEY,
    model: env.GEMINI_MODEL?.trim() || DEFAULT_GEMINI_MODEL,
    thinkingLevel: env.GEMINI_THINKING_LEVEL?.trim() || undefined,
    system: systemPrompt(validated.value),
    user: JSON.stringify({
      ingredients: validated.value.ingredients,
      maxMinutes: validated.value.maxMinutes,
      vegetarian: validated.value.vegetarian,
    }),
    responseSchema: RECIPES_SCHEMA,
  });
  if (!outcome.ok) {
    if (outcome.reason === "timeout") {
      return errorResponse(504, "ai_timeout", "Recipe generation timed out.", headers);
    }
    return errorResponse(502, "ai_error", "Recipe generation failed.", headers);
  }

  const recipes = validateRecipesResponse(outcome.data, {
    maxMinutes: validated.value.maxMinutes,
    selected: validated.value.ingredients,
  });
  if (!recipes.ok) {
    return errorResponse(
      502,
      "ai_invalid",
      "Recipe generation returned an invalid payload.",
      headers,
    );
  }
  return json(200, recipes.value, headers);
}
